/**
 * Minimal deterministic DSP kit used to synthesise the Widoken ad soundtrack
 * and sound effects. No third-party audio assets are used anywhere in this
 * production: every sample in public/audio is generated by this code.
 */

export const SR = 44100

export function mulberry32(seed) {
  let a = seed >>> 0
  return function random() {
    a = (a + 0x6d2b79f5) >>> 0
    let t = a
    t = Math.imul(t ^ (t >>> 15), t | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

export function seconds(n) {
  return Math.max(0, Math.round(n * SR))
}

/** Stereo track helper. */
export class Track {
  constructor(durationSeconds, channels = 2) {
    this.length = seconds(durationSeconds)
    this.data = Array.from({ length: channels }, () => new Float32Array(this.length))
  }

  addMono(mono, gain = 1, pan = 0, offsetSeconds = 0) {
    const offset = seconds(offsetSeconds)
    const left = Math.min(1, Math.max(0, (pan + 1) / 2))
    const right = Math.min(1, Math.max(0, (1 - pan) / 2))
    for (let i = 0; i < mono.length; i += 1) {
      const j = offset + i
      if (j >= this.length) break
      const s = mono[i] * gain
      this.data[0][j] += s * left
      this.data[1][j] += s * right
    }
  }

  addStereo(left, right, gain = 1, offsetSeconds = 0) {
    const offset = seconds(offsetSeconds)
    for (let i = 0; i < left.length; i += 1) {
      const j = offset + i
      if (j >= this.length) break
      this.data[0][j] += left[i] * gain
      this.data[1][j] += right[i] * gain
    }
  }

  /** Transparent below the threshold, asymptotically bounded at 1. */
  finish({ targetRms = 0.13, ceiling = 0.95, threshold = 0.68 } = {}) {
    let sum = 0
    let count = 0
    let peak = 0
    for (const channel of this.data) {
      for (let i = 0; i < channel.length; i += 1) {
        const value = channel[i]
        sum += value * value
        count += 1
        const magnitude = Math.abs(value)
        if (magnitude > peak) peak = magnitude
      }
    }
    const rms = count > 0 ? Math.sqrt(sum / count) : 0
    let gain = rms > 0 ? targetRms / rms : 1
    if (peak * gain > ceiling) gain = ceiling / peak
    for (const channel of this.data) {
      for (let i = 0; i < channel.length; i += 1) {
        channel[i] = softClipper(channel[i] * gain, threshold)
      }
    }
    return this
  }
}

export function softClip(x) {
  return Math.tanh(x)
}

/** Transparent below the threshold, asymptotically bounded at 1. */
export function softClipper(x, threshold = 0.68) {
  const magnitude = Math.abs(x)
  if (magnitude <= threshold) return x
  const sign = x < 0 ? -1 : 1
  const over = magnitude - threshold
  return sign * (threshold + (1 - threshold) * (1 - Math.exp(-over / (1 - threshold))))
}

/** Chamberlin state-variable filter. */
export class SVF {
  constructor() {
    this.low = 0
    this.band = 0
  }

  process(x, cutoff, q) {
    const f = 2 * Math.sin(Math.PI * Math.min(Math.max(cutoff, 20), SR * 0.45) / SR)
    const damp = 1 / Math.max(q, 0.6)
    const high = x - this.low - damp * this.band
    this.band += f * high
    this.low += f * this.band
    return { low: this.low, band: this.band, high }
  }
}

export function onePoleLowpass(input, cutoff) {
  const out = new Float32Array(input.length)
  const alpha = 1 - Math.exp((-2 * Math.PI * cutoff) / SR)
  let z = 0
  for (let i = 0; i < input.length; i += 1) {
    z += alpha * (input[i] - z)
    out[i] = z
  }
  return out
}

export function onePoleHighpass(input, cutoff) {
  const out = new Float32Array(input.length)
  const alpha = 1 - Math.exp((-2 * Math.PI * cutoff) / SR)
  let z = 0
  for (let i = 0; i < input.length; i += 1) {
    z += alpha * (input[i] - z)
    out[i] = input[i] - z
  }
  return out
}

/** Schroeder reverb: four parallel combs into two series allpasses. */
export function reverb(input, { mix = 0.25, decay = 0.84, damp = 0.28, width = 1 } = {}) {
  const combDelays = [1557, 1617, 1491, 1422]
  const combGains = [0.78, 0.76, 0.74, 0.72]
  const allpassDelays = [225, 556]
  const outL = new Float32Array(input.length)
  const outR = new Float32Array(input.length)

  for (let c = 0; c < combDelays.length; c += 1) {
    const d = combDelays[c]
    const buf = new Float32Array(input.length + d)
    const g = combGains[c]
    let z = 0
    for (let i = 0; i < input.length; i += 1) {
      const delayed = buf[i]
      z += damp * (delayed - z)
      buf[i + d] = input[i] + z * g
    }
    for (let i = 0; i < input.length; i += 1) {
      outL[i] += buf[i] * 0.25
      outR[i] += buf[i] * 0.25
    }
  }

  for (const d of allpassDelays) {
    const buf = new Float32Array(input.length + d)
    for (let i = 0; i < input.length; i += 1) {
      const delayed = buf[i]
      const value = input[i] + delayed * 0.5
      buf[i + d] = delayed - value * 0.5
      outL[i] += value * 0.5
      outR[i] += value * 0.5
    }
  }

  const resultL = new Float32Array(input.length)
  const resultR = new Float32Array(input.length)
  for (let i = 0; i < input.length; i += 1) {
    const wetL = outL[i] * width
    const wetR = outR[i] * (2 - width)
    resultL[i] = input[i] * (1 - mix) + wetL * mix
    resultR[i] = input[i] * (1 - mix) + wetR * mix
  }
  return { left: resultL, right: resultR }
}

/** Stereo ping-pong delay. */
export function pingPong(input, { time = 0.28, feedback = 0.34, mix = 0.2 } = {}) {
  const d = seconds(time)
  const left = new Float32Array(input.length)
  const right = new Float32Array(input.length)
  const bufL = new Float32Array(input.length + d)
  const bufR = new Float32Array(input.length + d)
  for (let i = 0; i < input.length; i += 1) {
    const dl = bufL[i]
    const dr = bufR[i]
    bufL[i + d] = input[i] + dr * feedback
    bufR[i + d] = input[i] + dl * feedback
    left[i] = input[i] * (1 - mix) + dr * mix
    right[i] = input[i] * (1 - mix) + dl * mix
  }
  return { left, right }
}

/* ------------------------------------------------------------------ *
 * Instrument voices
 * ------------------------------------------------------------------ */

export function kick({ duration = 0.5, freqStart = 150, freqEnd = 46, pitchTime = 0.05, decay = 0.32, click = 0.4, drive = 1.8, rand = Math.random } = {}) {
  const n = seconds(duration)
  const out = new Float32Array(n)
  let phase = 0
  for (let i = 0; i < n; i += 1) {
    const t = i / SR
    const f = freqEnd + (freqStart - freqEnd) * Math.exp(-t / pitchTime)
    phase += (2 * Math.PI * f) / SR
    const env = Math.exp(-t / decay)
    let s = Math.sin(phase) * env
    if (t < 0.008) s += (rand() * 2 - 1) * click * (1 - t / 0.008)
    out[i] = Math.tanh(s * drive) / Math.tanh(drive)
  }
  return out
}

export function subBass({ duration = 0.5, freq = 55, decay = 0.28, attack = 0.006, level = 1 } = {}) {
  const n = seconds(duration)
  const out = new Float32Array(n)
  let phase = 0
  for (let i = 0; i < n; i += 1) {
    const t = i / SR
    phase += (2 * Math.PI * freq) / SR
    const env = Math.min(1, t / attack) * Math.exp(-t / decay)
    out[i] = (Math.sin(phase) * 0.92 + Math.sin(phase * 2) * 0.08) * env * level
  }
  return out
}

/** Detuned saw through a resonant filter with an envelope - the lead pluck. */
export function pluck({ duration = 0.4, freq = 440, cutoff = 900, cutoffPeak = 5200, q = 7, decay = 0.19, detune = 0.006, level = 1, rand = Math.random } = {}) {
  const n = seconds(duration)
  const out = new Float32Array(n)
  const filter = new SVF()
  const phases = [0, 0, 0]
  const detunes = [-detune, 0, detune]
  for (let i = 0; i < n; i += 1) {
    const t = i / SR
    let s = 0
    for (let k = 0; k < 3; k += 1) {
      const f = freq * (1 + detunes[k])
      phases[k] += f / SR
      if (phases[k] > 1) phases[k] -= 1
      s += phases[k] * 2 - 1
    }
    s /= 3
    const env = Math.min(1, t / 0.003) * Math.exp(-t / decay)
    const sweep = cutoff + (cutoffPeak - cutoff) * Math.exp(-t / 0.055)
    const filtered = filter.process(s * env, sweep, q).low
    out[i] = filtered * level
  }
  return out
}

/** Warm sustained pad. */
export function pad({ duration = 2, freq = 220, q = 1.1, cutoff = 1500, attack = 0.35, release = 0.6, level = 1, rand = Math.random } = {}) {
  const n = seconds(duration)
  const out = new Float32Array(n)
  const filter = new SVF()
  const phases = [0, 0, 0, 0, 0, 0]
  const detunes = [-0.008, -0.003, 0, 0.003, 0.008, 0.014]
  for (let i = 0; i < n; i += 1) {
    const t = i / SR
    let s = 0
    for (let k = 0; k < phases.length; k += 1) {
      const f = freq * (1 + detunes[k])
      phases[k] += f / SR
      if (phases[k] > 1) phases[k] -= 1
      s += phases[k] * 2 - 1
    }
    s /= phases.length
    const env = Math.min(1, t / attack) * Math.min(1, Math.max(0, (duration - t) / release))
    const filtered = filter.process(s, cutoff, q).low
    out[i] = filtered * env * level
  }
  return out
}

export function noiseBurst({ duration = 0.08, rand = Math.random } = {}) {
  const n = seconds(duration)
  const out = new Float32Array(n)
  for (let i = 0; i < n; i += 1) out[i] = rand() * 2 - 1
  return out
}

export function hat({ duration = 0.06, cutoff = 8200, decay = 0.018, level = 1, rand = Math.random } = {}) {
  const raw = noiseBurst({ duration, rand })
  const band = onePoleHighpass(raw, cutoff)
  const out = new Float32Array(raw.length)
  for (let i = 0; i < raw.length; i += 1) {
    out[i] = band[i] * Math.exp((-i / SR) / decay) * level
  }
  return out
}

export function clap({ duration = 0.3, rand = Math.random } = {}) {
  const n = seconds(duration)
  const out = new Float32Array(n)
  const offsets = [0, 0.011, 0.022]
  for (const offset of offsets) {
    const start = seconds(offset)
    for (let i = start; i < n; i += 1) {
      const t = (i - start) / SR
      out[i] += (rand() * 2 - 1) * Math.exp(-t / 0.012) * 0.5
    }
  }
  for (let i = seconds(0.03); i < n; i += 1) {
    const t = (i - seconds(0.03)) / SR
    out[i] += (rand() * 2 - 1) * Math.exp(-t / 0.09) * 0.32
  }
  const filtered = onePoleHighpass(out, 1100)
  const band = new SVF()
  const shaped = new Float32Array(n)
  for (let i = 0; i < n; i += 1) shaped[i] = band.process(filtered[i], 2200, 1.4).band
  return shaped
}

/** Reverse-sweeping riser. */
export function riser({ duration = 2, startCutoff = 320, endCutoff = 11000, level = 1, rand = Math.random } = {}) {
  const n = seconds(duration)
  const raw = noiseBurst({ duration, rand })
  const out = new Float32Array(n)
  const filter = new SVF()
  for (let i = 0; i < n; i += 1) {
    const t = i / n
    const cutoff = startCutoff * Math.pow(endCutoff / startCutoff, t * t)
    const env = Math.pow(t, 1.8)
    out[i] = filter.process(raw[i], cutoff, 4).band * env * level
  }
  return out
}

/** Cinematic impact: sub drop, noise burst, metallic ring. */
export function impact({ duration = 1.4, freqStart = 160, freqEnd = 34, level = 1, rand = Math.random } = {}) {
  const n = seconds(duration)
  const out = new Float32Array(n)
  let phase = 0
  for (let i = 0; i < n; i += 1) {
    const t = i / SR
    const f = freqEnd + (freqStart - freqEnd) * Math.exp(-t / 0.09)
    phase += (2 * Math.PI * f) / SR
    out[i] += Math.sin(phase) * Math.exp(-t / 0.38) * 0.9
  }
  const burst = noiseBurst({ duration, rand })
  const hp = onePoleHighpass(burst, 900)
  for (let i = 0; i < n; i += 1) {
    const t = i / SR
    out[i] += hp[i] * Math.exp(-t / 0.09) * 0.55
  }
  const ring = [431, 617, 941, 1297]
  for (const f of ring) {
    let p = 0
    for (let i = 0; i < n; i += 1) {
      const t = i / SR
      p += (2 * Math.PI * f) / SR
      out[i] += Math.sin(p) * Math.exp(-t / 0.5) * 0.07
    }
  }
  const shaped = new Float32Array(n)
  for (let i = 0; i < n; i += 1) shaped[i] = Math.tanh(out[i] * 1.5) * level
  return shaped
}

/** Short graphic transition whoosh. */
export function whoosh({ duration = 0.45, startCutoff = 380, endCutoff = 7200, reverse = false, level = 1, rand = Math.random } = {}) {
  const n = seconds(duration)
  const raw = noiseBurst({ duration, rand })
  const out = new Float32Array(n)
  const filter = new SVF()
  for (let i = 0; i < n; i += 1) {
    const t = i / n
    const shaped = reverse ? 1 - t : t
    const cutoff = startCutoff * Math.pow(endCutoff / startCutoff, shaped)
    const env = Math.sin(Math.PI * Math.min(1, Math.max(0, t)))
    out[i] = filter.process(raw[i], cutoff, 3.2).band * env * level
  }
  return out
}

/** Dry click / tick. */
export function click({ duration = 0.05, cutoff = 4200, level = 1, rand = Math.random } = {}) {
  const raw = noiseBurst({ duration, rand })
  const hp = onePoleHighpass(raw, cutoff)
  const out = new Float32Array(raw.length)
  for (let i = 0; i < raw.length; i += 1) {
    out[i] = hp[i] * Math.exp((-i / SR) / 0.006) * level
  }
  return out
}

/** Short tonal blip used for interface beats. */
export function blip({ duration = 0.16, freq = 880, freqEnd = 1320, level = 1 } = {}) {
  const n = seconds(duration)
  const out = new Float32Array(n)
  let phase = 0
  for (let i = 0; i < n; i += 1) {
    const t = i / SR
    const f = freq + (freqEnd - freq) * (t / duration)
    phase += (2 * Math.PI * f) / SR
    const env = Math.min(1, t / 0.004) * Math.exp(-t / (duration * 0.55))
    out[i] = Math.sin(phase) * env * level
  }
  return out
}

/** Metallic tank tread / hull clank. */
export function clank({ duration = 0.7, level = 1, rand = Math.random } = {}) {
  const n = seconds(duration)
  const out = new Float32Array(n)
  const partials = [186, 279, 412, 557, 763]
  for (let k = 0; k < partials.length; k += 1) {
    let p = 0
    const f = partials[k] * (1 + (rand() - 0.5) * 0.02)
    for (let i = 0; i < n; i += 1) {
      const t = i / SR
      p += (2 * Math.PI * f) / SR
      out[i] += Math.sin(p) * Math.exp(-t / (0.1 + k * 0.05)) * (0.3 / (k + 1))
    }
  }
  const burst = noiseBurst({ duration: 0.05, rand })
  const hp = onePoleHighpass(burst, 1800)
  for (let i = 0; i < burst.length; i += 1) out[i] += hp[i] * Math.exp((-i / SR) / 0.012) * 0.5
  const shaped = new Float32Array(n)
  for (let i = 0; i < n; i += 1) shaped[i] = Math.tanh(out[i] * 1.8) * level
  return shaped
}

/** Continuous tread rumble, one second, loopable. */
export function tread({ duration = 1, level = 1, rand = Math.random } = {}) {
  const n = seconds(duration)
  const raw = noiseBurst({ duration, rand })
  const filter = new SVF()
  const out = new Float32Array(n)
  for (let i = 0; i < n; i += 1) {
    const t = i / SR
    const rattle = 0.6 + 0.4 * Math.sin(2 * Math.PI * 14 * t)
    out[i] = filter.process(raw[i], 240, 1.6).low * rattle * level
  }
  // crossfade the tail into the head so the loop is seamless
  const fade = seconds(0.05)
  for (let i = 0; i < fade; i += 1) {
    const w = i / fade
    out[i] = out[i] * w + out[n - fade + i] * (1 - w)
  }
  return out.subarray(0, n - fade)
}

/** Tiny high-frequency scuttle used for the ant. */
export function scuttle({ duration = 0.5, level = 1, rand = Math.random } = {}) {
  const n = seconds(duration)
  const out = new Float32Array(n)
  let t = 0
  while (t < duration) {
    const at = seconds(t)
    const len = seconds(0.02)
    for (let i = 0; i < len && at + i < n; i += 1) {
      const local = i / SR
      out[at + i] += (rand() * 2 - 1) * Math.exp(-local / 0.004) * level * 0.5
    }
    t += 0.055 + rand() * 0.02
  }
  return onePoleHighpass(out, 3600)
}

/** Short "pop" for graphic reveals. */
export function pop({ duration = 0.24, freq = 180, freqEnd = 620, level = 1 } = {}) {
  const n = seconds(duration)
  const out = new Float32Array(n)
  let phase = 0
  for (let i = 0; i < n; i += 1) {
    const t = i / SR
    const f = freq + (freqEnd - freq) * Math.pow(t / duration, 0.55)
    phase += (2 * Math.PI * f) / SR
    const env = Math.min(1, t / 0.003) * Math.exp(-t / (duration * 0.4))
    out[i] = (Math.sin(phase) * 0.8 + Math.sin(phase * 2.01) * 0.2) * env * level
  }
  return out
}

/* ------------------------------------------------------------------ *
 * WAV writer (16 bit PCM stereo)
 * ------------------------------------------------------------------ */

export function writeWav(path, channels) {
  const numChannels = channels.length
  const numFrames = channels[0].length
  const bytesPerSample = 2
  const dataSize = numFrames * numChannels * bytesPerSample
  const buffer = Buffer.alloc(44 + dataSize)
  buffer.write('RIFF', 0)
  buffer.writeUInt32LE(36 + dataSize, 4)
  buffer.write('WAVE', 8)
  buffer.write('fmt ', 12)
  buffer.writeUInt32LE(16, 16)
  buffer.writeUInt16LE(1, 20)
  buffer.writeUInt16LE(numChannels, 22)
  buffer.writeUInt32LE(SR, 24)
  buffer.writeUInt32LE(SR * numChannels * bytesPerSample, 28)
  buffer.writeUInt16LE(numChannels * bytesPerSample, 32)
  buffer.writeUInt16LE(16, 34)
  buffer.write('data', 36)
  buffer.writeUInt32LE(dataSize, 40)
  let offset = 44
  for (let i = 0; i < numFrames; i += 1) {
    for (let c = 0; c < numChannels; c += 1) {
      const value = Math.max(-1, Math.min(1, channels[c][i]))
      buffer.writeInt16LE(Math.round(value * 32767), offset)
      offset += 2
    }
  }
  return buffer
}
